parameters.jsCode:
const body = $json.body || $json;

// Détection du statut et des données de paiement
const status = (body.status || body.transactionStatus || 'SUCCESS').toUpperCase();
const amount = Number(body.amount || body.montant || 1000);
const currency = body.currency || 'XAF';
const payerPhone = (body.phone || body.customer_phone || body.sender || '').replace(/[^0-9]/g, '');
const studentEmail = body.email || body.studentEmail || 'etudiant@campus360.app';
const studentId = body.studentId || body.userId || 'student-current';
const transactionId = body.transactionId || body.tx_ref || `tx-${Date.now()}`;
const operator = body.operator || body.paymentMethod || 'Mobile Money';

// Calcul du pack de jetons selon le montant
let tokensToAdd = 5;
let planName = 'Pack Découverte (5 candidatures IA)';

if (amount >= 5000) {
  tokensToAdd = 100;
  planName = 'Pass Illimité 30 Jours';
} else if (amount >= 2500) {
  tokensToAdd = 15;
  planName = 'Pack Pro Accélérateur (15 candidatures IA)';
}

const isValid = status === 'SUCCESS' || status === 'COMPLETED' || status === 'ACCEPTED';

return [{
  json: {
    isValid,
    status,
    amount,
    currency,
    payerPhone: payerPhone || '237690123456',
    studentEmail,
    studentId,
    transactionId,
    operator,
    tokensToAdd,
    planName,
    confirmedAt: new Date().toISOString()
  }
}];

